# Files that ./sync keeps in step, one "system | versioned" pair per line.
#
# [common] applies to every machine. [<hostname>] applies to that host only.
# The versioned path is relative to the folder with the section name.
# A system path that starts with ~/ expands to $HOME.

[common]
# bash
~/.config/bash/ | bash/
~/.bashrc | bash/bundle/bashrc
~/.bash_profile | bash/bundle/bash_profile
~/.profile | bash/bundle/profile
~/.inputrc | bash/bundle/inputrc
# fish
~/.config/fish/config.fish | fish/config.fish
~/.config/fish/conf.d/ | fish/conf.d/
# development environment (sourced by bash and fish)
~/.config/dev.env | misc/dev.env
# systemd
~/.config/systemd/ | systemd/
# rclone
~/.config/rclone/mount-mega.env | rclone/mount-mega.env
~/.config/rclone/rclone.conf.gpg | rclone/rclone.conf.gpg
# gnupg
~/.gnupg/gpg-agent.conf | gnupg/gpg-agent.conf
~/.gnupg/sshcontrol | gnupg/sshcontrol
# fonts configuration
~/.config/fontconfig/ | fontconfig/
# git
~/.config/git/ | git/
# helix
~/.config/helix/ | helix/
# zellij
~/.config/zellij/ | zellij/
# niri
~/.config/niri/ | niri/
# fuzzel
~/.config/fuzzel/ | fuzzel/
# mako
~/.config/mako/ | mako/
# swaylock
~/.config/swaylock/ | swaylock/
# rofimoji
~/.config/rofimoji.rc | rofimoji/rofimoji.rc
# alacritty
~/.config/alacritty/ | alacritty/
# paru
~/.config/paru/ | paru/
# yazi
~/.config/yazi/ | yazi/
# gitui
~/.config/gitui/ | gitui/
# zathura
~/.config/zathura/ | zathura/
# tridactyl
~/.config/tridactyl/ | tridactyl/
# lldb
~/.lldbinit | lldb/lldbinit
~/.lldb/scripts/ | lldb/scripts/
# Mime associations
~/.config/mimeapps.list | misc/mimeapps.list
# ssh
~/.ssh/config | ssh/config
# OTP tool
~/.config/otp/ | otp/
# imv
~/.config/imv/ | imv/
# protonmail bridge
~/.config/protonmail/bridge-v3/keychain.json | protonmail/keychain.json
# mxfeed
~/.config/mxfeed.toml | mxfeed.toml
# ghfeed
~/.config/ghfeed.toml | ghfeed.toml
# mxfeed
~/.config/rssfeed.toml | rssfeed.toml
# corral
~/.config/corral/ | corral/
# bat
~/.config/bat/ | bat/
# eza
~/.config/eza/ | eza/
# chroncal
~/.config/chroncal/ | chroncal/
# virt-viewer
~/.config/virt-viewer/ | virt-viewer/
# XDG user directories
~/.config/user-dirs.dirs | misc/user-dirs.dirs
# gtk
~/.config/gtk-3.0/settings.ini | gtk/gtk-3.0/settings.ini
~/.config/gtk-4.0/settings.ini | gtk/gtk-4.0/settings.ini
# cargo
~/.cargo/config.toml | cargo/config.toml
# greetd
/etc/greetd/config.toml | greetd/config.toml
# pam
/etc/pam.d/greetd | pam/greetd
/etc/pam.d/login | pam/login
# udev
/etc/udev/rules.d/99-uinput.rules | udev/99-uinput.rules

[behemoth]
# wayvnc
~/.config/wayvnc/ | wayvnc/
# samba
/etc/samba/smb.conf | samba/smb.conf
# evremap
/etc/evremap.toml | evremap/evremap.toml
# hosts
/etc/hosts | misc/hosts
# ufw
/etc/default/ufw | ufw/default/ufw
/etc/ufw/ufw.conf | ufw/ufw.conf
/etc/ufw/sysctl.conf | ufw/sysctl.conf
/etc/ufw/user.rules | ufw/user.rules
/etc/ufw/user6.rules | ufw/user6.rules
# sshd
/etc/ssh/sshd_config | ssh/sshd_config

[workmule]
# evremap
/etc/evremap.toml | evremap/evremap.toml
